import 'package:flutter/material.dart';
import 'package:lazerus_core/lazerus_core.dart';

import '../../../../../core/macros/modifiers/color_brightness_combine/color_brightness_combine_modifier.dart';
import '../macro_editor_node_module.dart';

final class ColorBrightnessCombineMacroEditorNodeModule
    extends MacroEditorNodeModule {
  @override
  String get kind => colorBrightnessCombineModifierKind;

  @override
  Iterable<MacroEditorPaletteEntry> paletteEntries(
    MacroEditorNodePresentationState state,
  ) => <MacroEditorPaletteEntry>[
    const MacroEditorPaletteEntry(
      id: 'palette.color-brightness-combine',
      moduleKind: colorBrightnessCombineModifierKind,
      section: MacroEditorPaletteSection.modules,
      icon: Icons.merge_type_outlined,
      title: 'Color + brightness',
      subtitle: 'HSV Value combiner',
    ),
  ];

  @override
  MacroNode? createNode(
    MacroEditorPaletteEntry entry, {
    required MacroEditorNewId newId,
  }) {
    final id = newId();
    return MacroNode(
      id: id,
      kind: kind,
      displayName: 'Color + brightness',
      ports: ColorBrightnessCombineModifierFactory.portsForNode(id),
    );
  }

  @override
  Widget buildInspector(
    BuildContext context,
    MacroEditorNodeViewContext nodeContext,
  ) => MacroEditorNodeInspectorCard(
    icon: Icons.merge_type_outlined,
    title: titleFor(nodeContext.node),
    enabled: nodeContext.state.enabled,
    onRemove: nodeContext.removeNode,
    child: const Text(
      'Combines HSV color with a normalized HSV Value signal. '
      'It does not issue a device brightness command itself.',
    ),
  );
}
